import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BSwSpTvy.js";const i="/zed-custom/azure-anthropic-demo.gif",m=JSON.parse('{"title":"☁️ Azure Anthropic & Token Caching","description":"","frontmatter":{},"headers":[],"relativePath":"features/azure-anthropic.md","filePath":"features/azure-anthropic.md"}'),n={name:"features/azure-anthropic.md"};function c(s,e,d,u,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="☁️-azure-anthropic-token-caching" tabindex="-1">☁️ Azure Anthropic &amp; Token Caching <a class="header-anchor" href="#☁️-azure-anthropic-token-caching" aria-label="Permalink to &quot;☁️ Azure Anthropic &amp; Token Caching&quot;">​</a></h1><h2 id="_1-zero-friction-azure-support" tabindex="-1">1. Zero-Friction Azure Support <a class="header-anchor" href="#_1-zero-friction-azure-support" aria-label="Permalink to &quot;1. Zero-Friction Azure Support&quot;">​</a></h2><p>If you use enterprise Azure Anthropic endpoints, you&#39;re likely familiar with <code>404 DeploymentNotFound</code> errors. Standard Zed passes hardcoded string identifiers (like <code>claude-3-5-sonnet-20241022</code>) which Azure strictly rejects in favor of exact deployment names.</p><p>This fork intercepts these calls natively. If you specify a custom <code>api_url</code> in your settings, Zed automatically forwards the exact <code>serde_name</code> deployment model you provided, completely eliminating the need for local python proxy servers.</p><h2 id="_2-token-caching-visualization" tabindex="-1">2. Token Caching Visualization <a class="header-anchor" href="#_2-token-caching-visualization" aria-label="Permalink to &quot;2. Token Caching Visualization&quot;">​</a></h2><p>Anthropic&#39;s Prompt Caching feature is incredibly powerful, dramatically reducing latency and API costs for large contexts. However, standard Zed hides these metrics deeply within debug menus or disables them outright.</p><p>In this build, the <code>show_turn_stats</code> visualization is <strong>enabled by default</strong>.</p><p><img src="'+i+'" alt="Azure Anthropic Token Caching Demo"></p><p>Whenever you send a message, you immediately see beautifully formatted badges above the feedback buttons:</p><ul><li><strong><code>X cached</code></strong>: How many tokens were instantly pulled from the Anthropic cache.</li><li><strong><code>+X saved</code></strong>: The exact number of tokens (and money) you saved on this turn.</li></ul><p>No configuration tweaking required. Just pristine, real-time ROI tracking directly in the UI.</p>',11)])])}const f=t(n,[["render",c]]);export{m as __pageData,f as default};
